// Temporary integrated current-source full-trim acceptance consumer.
using AtomUI;
using AtomUI.Controls.Localization;
using AtomUI.Desktop.Controls;
using AtomUI.Localization;
using AtomUI.Registration;
using AtomUI.Theme;
using AtomUI.Theme.Algorithms;
using AtomUI.Theme.Configuration;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Threading;
using Avalonia.VisualTree;
using Button = AtomUI.Desktop.Controls.Button;
using Window = AtomUI.Desktop.Controls.Window;

AppBuilder.Configure<ConsumerApp>().UsePlatformDetect().SetupWithoutStarting();
var app = (ConsumerApp)Application.Current!;
var button = new Button { Content = "Integrated trim", IsMotionEnabled = false };
var window = new Window { Width = 600, Height = 500, Content = button };
window.Show();
Dispatcher.UIThread.RunJobs();
Check(ControlRegistrationRuntime.IsTrimmed, "selected registration mode");
Check(window.Template is not null && window.GetVisualDescendants().Any(), "Window template executes");
Check(button.Template is not null && button.GetVisualDescendants().Any(), "Button template executes");
Check(app.TryFindResource(typeof(Window), out var theme) && theme is Avalonia.Styling.ControlTheme, "Window resource resolves");
var manager = app.GetThemeManager()!;
Check(manager.CurrentTheme is not null, "initial compiled theme exists");
var localizer = app.GetLocalizer()!;
Check(localizer.Get(CommonLangResourceKind.Ok) == "Ok", "English lookup");
app.GetLanguageManager()!.ChangeLanguage(LanguageTags.ZhCN);
Check(localizer.Get(CommonLangResourceKind.Ok) == "确定", "Chinese lookup");
var change = manager.ApplyThemeAsync(new ThemeRequest(IThemeManager.DEFAULT_THEME_ID,
    new ThemeConfigBuilder().WithAlgorithms(ThemeAlgorithm.Default, ThemeAlgorithm.Dark).Build(), ThemeTransitionReason.UserRequest));
while (!change.IsCompleted) { Dispatcher.UIThread.RunJobs(); }
Check(change.GetAwaiter().GetResult().Status == ThemeTransitionStatus.Committed && manager.CurrentTheme!.Appearance == ThemeAppearance.Dark, "dark compilation and commit");
window.Close();
Console.WriteLine("INTEGRATED_TRIM_PASS");

static void Check(bool condition, string name)
{
    if (!condition) { throw new InvalidOperationException("INTEGRATED_TRIM_FAIL " + name); }
    Console.WriteLine("CHECK " + name);
}

public sealed class ConsumerApp : Application
{
    public override void Initialize()
    {
        this.UseAtomUI(builder =>
        {
            builder.UseLanguages(LanguageTags.EnUS, [LanguageTags.EnUS, LanguageTags.ZhCN, LanguageTags.ZhTW]);
            builder.UseDesktopControls();
        });
    }
}

