const { chromium } = require('C:/Users/atomware/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs = require('fs');
const path = require('path');
(async () => {
  const events = [];
  const requests = new Map();
  const browser = await chromium.launch({ executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe', headless:true });
  const result = {host:'http://127.0.0.1:57073/',events};
  try {
    const page = await browser.newPage({viewport:{width:1440,height:1000}});
    const cdp = await page.context().newCDPSession(page);
    await cdp.send('Network.enable');
    await cdp.send('Log.enable');
    await cdp.send('Runtime.enable');
    cdp.on('Network.requestWillBeSent', e => requests.set(e.requestId,{url:e.request.url,type:e.type,documentURL:e.documentURL,initiator:e.initiator}));
    cdp.on('Network.responseReceived', e => {if(e.response.status>=400) events.push({kind:'http-error',request:requests.get(e.requestId),status:e.response.status,statusText:e.response.statusText,url:e.response.url,type:e.type});});
    cdp.on('Network.loadingFailed', e => events.push({kind:'request-failed',request:requests.get(e.requestId),errorText:e.errorText,canceled:e.canceled}));
    cdp.on('Log.entryAdded', e => events.push({kind:'cdp-log',...e.entry}));
    cdp.on('Runtime.consoleAPICalled', e => {if(['warning','error'].includes(e.type)) events.push({kind:'cdp-console',...e});});
    page.on('console', m=>events.push({kind:'console',type:m.type(),text:m.text(),location:m.location()}));
    page.on('pageerror', e=>events.push({kind:'pageerror',message:e.message,stack:e.stack}));
    await page.goto(result.host,{waitUntil:'load',timeout:30000});
    await page.waitForTimeout(15000);
    result.url=page.url();
    result.canvas=await page.locator('canvas').evaluateAll(xs=>xs.map(x=>({width:x.width,height:x.height})));
    result.splash=await page.locator('.splash-error').allTextContents();
    await page.screenshot({path:path.join(__dirname,'task10-browser-attribution.png')});
  } finally {
    await browser.close();
    result.ownedBrowserClosed=true;
    fs.writeFileSync(path.join(__dirname,'task10-browser-attribution.json'),JSON.stringify(result,null,2));
    console.log(JSON.stringify(result));
  }
})().catch(e=>{console.error(e);process.exitCode=1;});

