$ErrorActionPreference = 'Stop'
$baselineRoot = 'C:/Users/atomware/AppData/Local/Temp/AtomUI-startup-baseline-20261010'
$candidateRoot = 'C:/Users/atomware/AppData/Local/Temp/AtomUI-task10-acceptance-20261011'
$output = Join-Path $PSScriptRoot 'task10-ab-samples.jsonl'
if (Test-Path -LiteralPath $output) { throw 'Evidence exists' }
$executables = @{
    baseline = "$baselineRoot/baseline-bin/StartupProbe.exe"
    candidate = "$candidateRoot/candidate-bin/StartupProbe.exe"
}
$original = Get-Content -Raw "$baselineRoot/baseline-binary-manifest.json" | ConvertFrom-Json
foreach ($entry in $original) {
    if ((Get-FileHash -LiteralPath (Join-Path "$baselineRoot/baseline-bin" $entry.RelativePath)).Hash -ne $entry.SHA256) { throw 'Baseline changed' }
}
foreach ($file in @('Program.cs','StartupProbe.csproj')) {
    if ((Get-FileHash "$baselineRoot/$file").Hash -ne (Get-FileHash "$candidateRoot/$file").Hash) { throw 'Probe source differs' }
}
New-Item -ItemType Directory -Path "$output.logs" | Out-Null
for ($round = 1; $round -le 10; $round++) {
    foreach ($scenario in @('plain','atom-plain','atom-window')) {
        $versions = if ($round % 2 -eq 1) { @('baseline','candidate') } else { @('candidate','baseline') }
        foreach ($version in $versions) {
            $executable = (Resolve-Path -LiteralPath $executables[$version]).Path
            $start = [Diagnostics.ProcessStartInfo]::new()
            $start.FileName = $executable
            $start.WorkingDirectory = [IO.Path]::GetDirectoryName($executable)
            $start.UseShellExecute = $false
            $start.CreateNoWindow = $true
            $start.RedirectStandardOutput = $true
            $start.RedirectStandardError = $true
            $start.ArgumentList.Add($scenario)
            $launchTick = [Diagnostics.Stopwatch]::GetTimestamp()
            $start.ArgumentList.Add($launchTick.ToString([Globalization.CultureInfo]::InvariantCulture))
            $process = [Diagnostics.Process]::new()
            $process.StartInfo = $start
            try {
                if (!$process.Start()) { throw 'Process start failed' }
                $ownedPid = $process.Id
                $stdoutTask = $process.StandardOutput.ReadToEndAsync()
                $stderrTask = $process.StandardError.ReadToEndAsync()
                if (!$process.WaitForExit(20000)) { throw "Timeout $version $scenario $ownedPid" }
                $stdout = $stdoutTask.GetAwaiter().GetResult()
                $stderr = $stderrTask.GetAwaiter().GetResult()
                $prefix = "$output.logs/$round-$scenario-$version-pid$ownedPid"
                Set-Content -LiteralPath "$prefix.stdout.txt" -Value $stdout
                Set-Content -LiteralPath "$prefix.stderr.txt" -Value $stderr
                if ($process.ExitCode -ne 0) { throw "Exit=$($process.ExitCode) $stderr" }
                $lines = @($stdout -split "`n" | Where-Object { $_.Trim().StartsWith('{') })
                if ($lines.Count -ne 1) { throw 'Expected one record' }
                $record = $lines[0] | ConvertFrom-Json
                if ($record.pid -ne $ownedPid -or $record.scenario -ne $scenario) { throw 'Identity mismatch' }
                $record | Add-Member -NotePropertyMembers @{ round=$round; version=$version; executable=$executable; executableSha256=(Get-FileHash -LiteralPath $executable).Hash; launchTick=$launchTick; completedUtc=[DateTime]::UtcNow.ToString('O') }
                $record | ConvertTo-Json -Compress | Add-Content -LiteralPath $output
                Write-Output "$round $scenario $version pid=$ownedPid init=$($record.initializeDurationMs) render=$($record.firstRenderFromLaunchMs)"
            }
            finally {
                if ($process.Id -and !$process.HasExited) { $process.Kill($true); $process.WaitForExit() }
                $process.Dispose()
            }
        }
    }
}
