$ErrorActionPreference='Stop'
Add-Type -Path 'D:/workspace/projects/AtomUI/.artifacts/bin/Release/toolchain/illink10/net10.0/Mono.Cecil.dll'
$candidate='C:/Users/atomware/AppData/Local/Temp/AtomUI-task10-acceptance-20261011/candidate-bin'
$phase="C:/Users/atomware/AppData/Local/Temp/AtomUI-task10-phase-$Level"
if(Test-Path -LiteralPath $phase) { throw 'Phase directory exists' }
Copy-Item -LiteralPath $candidate -Destination $phase -Recurse
$resolver=[Mono.Cecil.DefaultAssemblyResolver]::new()
$resolver.AddSearchDirectory($phase)
$resolver.AddSearchDirectory('C:/Program Files/dotnet/shared/Microsoft.NETCore.App/10.0.12')
$reader=[Mono.Cecil.ReaderParameters]::new();$reader.AssemblyResolver=$resolver
function Mark($module,$processor,$before,$label) {
    $tick=$module.ImportReference([Diagnostics.Stopwatch].GetMethod('GetTimestamp'))
    $write=$module.ImportReference([Console].GetMethod('WriteLine',[type[]]@([string],[object])))
    $instructions=@(
        [Mono.Cecil.Cil.Instruction]::Create([Mono.Cecil.Cil.OpCodes]::Ldstr,"PHASE|$label|{0}"),
        [Mono.Cecil.Cil.Instruction]::Create([Mono.Cecil.Cil.OpCodes]::Call,$tick),
        [Mono.Cecil.Cil.Instruction]::Create([Mono.Cecil.Cil.OpCodes]::Box,$module.TypeSystem.Int64),
        [Mono.Cecil.Cil.Instruction]::Create([Mono.Cecil.Cil.OpCodes]::Call,$write)
    )
    foreach($instruction in $instructions) { $processor.InsertBefore($before,$instruction) }
    if($label.EndsWith('/before')) {
        foreach($instruction in $processor.Body.Instructions) {
            if($instruction.Operand -is [Mono.Cecil.Cil.Instruction] -and $instruction.Operand -eq $before) { $instruction.Operand=$instructions[0] }
        }
    }
}
function Instrument($module,$typeName,$methodName,$select) {
    $type=$module.GetTypes() | Where-Object FullName -eq $typeName
    $methods=@($type.Methods | Where-Object {$_.Name -eq $methodName -and $_.HasBody})
    foreach($method in $methods) {
        foreach($instruction in $method.Body.Instructions) {
            if($instruction.OpCode.OperandType -eq [Mono.Cecil.Cil.OperandType]::ShortInlineBrTarget) {
                $longName=$instruction.OpCode.Code.ToString() -replace '_S$',''
                $instruction.OpCode=[Mono.Cecil.Cil.OpCodes].GetField($longName).GetValue($null)
            }
        }
        $processor=$method.Body.GetILProcessor()
        $calls=@($method.Body.Instructions | Where-Object { $_.Operand -is [Mono.Cecil.MethodReference] -and (& $select $_.Operand) })
        $index=0
        foreach($call in $calls) {
            $label="$typeName.$methodName/$index/$($call.Operand.DeclaringType.FullName).$($call.Operand.Name)"
            Mark $module $processor $call "$label/before"
            Mark $module $processor $call.Next "$label/after"
            "$label"
            $index++
        }
    }
}
