Move-Item -LiteralPath "$phase/Avalonia.Controls.instrumented.dll" -Destination "$phase/Avalonia.Controls.dll" -Force
for($round=1;$round -le 3;$round++) {
    $exe="$phase/StartupProbe.exe"
