function Read-Surface($file) {
    $module=[Mono.Cecil.ModuleDefinition]::ReadModule($file)
    try {
        foreach($type in $module.GetTypes()) {
            $visible=$type.IsPublic -or $type.IsNestedPublic -or $type.IsNestedFamily -or $type.IsNestedFamilyOrAssembly
            $owner=$type.DeclaringType
            while($visible -and $null -ne $owner) {
                $visible=$owner.IsPublic -or $owner.IsNestedPublic -or $owner.IsNestedFamily -or $owner.IsNestedFamilyOrAssembly
                $owner=$owner.DeclaringType
            }
            if(!$visible) { continue }
            "TYPE $($type.FullName) $($type.Attributes) BASE $($type.BaseType.FullName)"
            foreach($iface in $type.Interfaces) { "INTERFACE $($type.FullName) $($iface.InterfaceType.FullName)" }
            foreach($method in $type.Methods) {
                if($method.IsPublic -or $method.IsFamily -or $method.IsFamilyOrAssembly) {
                    "METHOD $($method.FullName) $($method.Attributes)"
