// Temporary startup acceptance probe. Delete with Task 10 after the baseline/candidate comparison.
using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Text.Json;
using AtomUI;
using AtomUI.Desktop.Controls;
using Avalonia;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Media;
using Avalonia.Threading;
using AvaloniaWindow = Avalonia.Controls.Window;

internal static class Program
{
    [STAThread]
    public static int Main(string[] args)
    {
        Metrics.MainTick = Stopwatch.GetTimestamp();
        Metrics.Scenario = args[0];
        Metrics.LaunchTick = long.Parse(args[1]);
        try
        {
            AppBuilder.Configure<ProbeApplication>()
                .UsePlatformDetect()
                .With(new Win32PlatformOptions
                {
                    RenderingMode = [Win32RenderingMode.AngleEgl, Win32RenderingMode.Software],
                    CompositionMode = [Win32CompositionMode.WinUIComposition, Win32CompositionMode.DirectComposition,
                        Win32CompositionMode.LowLatencyDxgiSwapChain, Win32CompositionMode.RedirectionSurface]
                })
                .With(new FontManagerOptions
                {
                    FontFallbacks = [new FontFallback { FontFamily = new FontFamily("Microsoft YaHei") }]
                })
                .StartWithClassicDesktopLifetime(args);
            return Metrics.Written ? 0 : 2;
        }
        catch (Exception exception)
        {
            Console.Error.WriteLine(exception);
            return 1;
        }
    }
}

public sealed class ProbeApplication : Application
{
    public override void Initialize()
    {
        Metrics.InitializeStartTick = Stopwatch.GetTimestamp();
        var totalBefore = GC.GetTotalAllocatedBytes(true);
        var threadBefore = GC.GetAllocatedBytesForCurrentThread();
        if (Metrics.Scenario != "plain")
        {
            InitializeAtomUI();
        }
        Metrics.InitializeThreadAllocatedBytes = GC.GetAllocatedBytesForCurrentThread() - threadBefore;
        Metrics.InitializeAllocatedBytes = GC.GetTotalAllocatedBytes(true) - totalBefore;
        Metrics.InitializeEndTick = Stopwatch.GetTimestamp();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private void InitializeAtomUI()
    {
        this.UseAtomUI(builder => builder.UseDesktopControls());
    }

    public override void OnFrameworkInitializationCompleted()
    {
        if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
        {
            AvaloniaWindow window = Metrics.Scenario == "atom-window" ? CreateAtomWindow() : new PlainProbeWindow();
            window.Width = 800;
            window.Height = 600;
            window.Title = "AtomUI startup baseline";
            window.Opened += (_, _) => Metrics.OpenedTick = Stopwatch.GetTimestamp();
            desktop.MainWindow = window;
        }
        base.OnFrameworkInitializationCompleted();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static AvaloniaWindow CreateAtomWindow() => new AtomProbeWindow();
}

internal sealed class PlainProbeWindow : AvaloniaWindow
{
    protected override Type StyleKeyOverride => typeof(AvaloniaWindow);
    public override void Render(DrawingContext context)
    {
        base.Render(context);
        Metrics.RecordRender(context, this);
    }
}

internal sealed class AtomProbeWindow : AtomUI.Desktop.Controls.Window
{
    public override void Render(DrawingContext context)
    {
        base.Render(context);
        Metrics.RecordRender(context, this);
    }
}

internal static class Metrics
{
    public static string Scenario = "";
    public static long LaunchTick;
    public static long MainTick;
    public static long InitializeStartTick;
    public static long InitializeEndTick;
    public static long InitializeAllocatedBytes;
    public static long InitializeThreadAllocatedBytes;
    public static long OpenedTick;
    public static bool Written;

    public static void RecordRender(DrawingContext context, AvaloniaWindow window)
    {
        context.FillRectangle(Brushes.Magenta, new Rect(12, 12, 8, 8));
        if (Written || OpenedTick == 0)
        {
            return;
        }
        var renderTick = Stopwatch.GetTimestamp();
        Written = true;
        var result = new
        {
            scenario = Scenario,
            pid = Environment.ProcessId,
            runtime = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,
            platform = "Win32;AngleEgl,Software;WinUIComposition,DirectComposition,LowLatencyDxgiSwapChain,RedirectionSurface",
            configuration = "Release;net10.0;Avalonia12.1.3;800x600;window-render-sentinel-8x8",
            mainFromLaunchMs = Ms(MainTick - LaunchTick),
            initializeStartFromMainMs = Ms(InitializeStartTick - MainTick),
            initializeStartFromLaunchMs = Ms(InitializeStartTick - LaunchTick),
            initializeDurationMs = Ms(InitializeEndTick - InitializeStartTick),
            initializeAllocatedBytes = InitializeAllocatedBytes,
            initializeThreadAllocatedBytes = InitializeThreadAllocatedBytes,
            openedFromMainMs = Ms(OpenedTick - MainTick),
            openedFromLaunchMs = Ms(OpenedTick - LaunchTick),
            firstRenderFromMainMs = Ms(renderTick - MainTick),
            firstRenderFromLaunchMs = Ms(renderTick - LaunchTick),
            renderAfterOpenedMs = Ms(renderTick - OpenedTick)
        };
        Console.WriteLine(JsonSerializer.Serialize(result));
        Dispatcher.UIThread.Post(window.Close, DispatcherPriority.Background);
    }
    private static double Ms(long ticks) => ticks * 1000.0 / Stopwatch.Frequency;
}
## Measure.ps1
param(
    [string]$Executable = (Join-Path $PSScriptRoot 'baseline-bin/StartupProbe.exe'),
    [int]$Samples = 10,
    [string]$Output = (Join-Path $PSScriptRoot 'baseline-samples.jsonl'),
    [int]$TimeoutMs = 20000
)
$ErrorActionPreference = 'Stop'
$Executable = (Resolve-Path -LiteralPath $Executable).Path
if (Test-Path -LiteralPath $Output) { throw "Output already exists: $Output" }
$runLogRoot = $Output + '.logs'
New-Item -ItemType Directory -Path $runLogRoot | Out-Null
$scenarios = @('plain', 'atom-plain', 'atom-window')
for ($iteration = 1; $iteration -le $Samples; $iteration++) {
    foreach ($scenario in $scenarios) {
        $start = [Diagnostics.ProcessStartInfo]::new()
        $start.FileName = $Executable
        $start.WorkingDirectory = [IO.Path]::GetDirectoryName($Executable)
        $start.UseShellExecute = $false
        $start.CreateNoWindow = $true
        $start.RedirectStandardOutput = $true
        $start.RedirectStandardError = $true
        $start.ArgumentList.Add($scenario)
        $launchTick = [Diagnostics.Stopwatch]::GetTimestamp()
        $start.ArgumentList.Add($launchTick.ToString([Globalization.CultureInfo]::InvariantCulture))
        $process = [Diagnostics.Process]::new()
        $process.StartInfo = $start
        try {
            if (!$process.Start()) { throw 'Process.Start failed' }
            $ownedPid = $process.Id
            $stdoutTask = $process.StandardOutput.ReadToEndAsync()
            $stderrTask = $process.StandardError.ReadToEndAsync()
            if (!$process.WaitForExit($TimeoutMs)) {
                $process.Kill($true)
                $process.WaitForExit()
                throw "Timeout: $scenario iteration=$iteration pid=$ownedPid executable=$Executable"
            }
            $stdout = $stdoutTask.GetAwaiter().GetResult()
            $stderr = $stderrTask.GetAwaiter().GetResult()
            $prefix = Join-Path $runLogRoot "$iteration-$scenario-pid$ownedPid"
            Set-Content -LiteralPath ($prefix + '.stdout.txt') -Value $stdout
            Set-Content -LiteralPath ($prefix + '.stderr.txt') -Value $stderr
            if ($process.ExitCode -ne 0) { throw "Exit=$($process.ExitCode) pid=$ownedPid scenario=$scenario stderr=$stderr" }
            $jsonLine = @($stdout -split "`n" | Where-Object { $_.Trim().StartsWith('{') })
            if ($jsonLine.Count -ne 1) { throw "Expected one JSON record, got $($jsonLine.Count)" }
            $record = $jsonLine[0] | ConvertFrom-Json
            if ($record.pid -ne $ownedPid -or $record.scenario -ne $scenario) { throw 'Process/config identity mismatch' }
            $record | Add-Member -NotePropertyName iteration -NotePropertyValue $iteration
            $record | Add-Member -NotePropertyName executable -NotePropertyValue $Executable
            $record | Add-Member -NotePropertyName launchTick -NotePropertyValue $launchTick
            $record | Add-Member -NotePropertyName completedUtc -NotePropertyValue ([DateTime]::UtcNow.ToString('O'))
            $record | ConvertTo-Json -Compress | Add-Content -LiteralPath $Output
            Write-Output "iteration=$iteration scenario=$scenario pid=$ownedPid Initialize=$([Math]::Round($record.initializeDurationMs,2))ms Opened=$([Math]::Round($record.openedFromLaunchMs,2))ms Render=$([Math]::Round($record.firstRenderFromLaunchMs,2))ms"
        }
        finally {
            if ($process.Id -and !$process.HasExited) { $process.Kill($true); $process.WaitForExit() }
            $process.Dispose()
        }
    }
}

